let taskFilter='全部状态';
function transferPanel(content){const anchor=$('#global-transfer'),app=$('#app').getBoundingClientRect(),r=anchor.getBoundingClientRect();if(!$('#popover').children.length)popReturnFocus=document.activeElement;closePop(false);$('#popover').innerHTML=`<section class="popover transfer-manager" role="dialog" aria-label="全局传输管理器"><header class="pop-head"><strong>全局传输管理器</strong><button id="close-pop" aria-label="关闭传输管理器">✕</button></header><label class="field"><span>任务状态</span><select id="task-filter">${['全部状态','传输中','已暂停','失败','已完成','已取消'].map(v=>`<option ${v===taskFilter?'selected':''}>${v}</option>`).join('')}</select></label><div class="transfer-rows">${content}</div></section>`;const p=$('.transfer-manager'),w=p.offsetWidth,h=p.offsetHeight;p.style.left=Math.max(12,Math.min(app.width-w-12,r.right-app.left-w))+'px';p.style.top=Math.max(12,Math.min(app.height-h-12,r.bottom-app.top+8))+'px';p.querySelector('button').focus()}
function showTasks(){transferPanel(tasks.length?tasks.map((t,i)=>({t,i})).filter(({t})=>taskFilter==='全部状态'||t.status===taskFilter).map(({t,i})=>`<article class="host-row"><div class="host-main"><strong>${esc(t.name)}</strong><p>${t.direction==='upload'?'上传':'下载'} · ${t.status} · ${t.mode||'默认'}</p><small>${esc(t.ownerName||'')} · ${esc(t.ownerAddress||'')}<br>${esc(t.sourcePath||'')} → ${esc(t.targetPath||'')}</small></div><button data-pause-task="${i}" ${!['传输中','已暂停'].includes(t.status)?'disabled':''}>${t.status==='已暂停'?'继续':'暂停'}</button><button data-fail-task="${i}" ${t.status!=='传输中'?'disabled':''}>演示失败</button><button data-retry-task="${i}" ${t.status!=='失败'?'disabled':''}>重试</button><button data-cancel-task="${i}" ${['已完成','已取消'].includes(t.status)?'disabled':''}>取消</button></article>`).join('')||'<div class="empty">该状态暂无任务</div>':'<div class="empty">暂无传输任务<br><small>KVM 不提供文件传输；其他会话的任务继续运行。</small></div>')}
let aiPosition=null,aiPolicy='确认后执行',aiModel='vision-chat-2',aiEffort='中',aiDrafts={},aiMessages={},aiMaximized=false,aiHistory=[],aiStage='idle',aiMode='power',imageAuthorized=false,inputLease=false,observationFresh=false;
