function aiSnapshot(){return {owner:protocol,stage:aiStage,mode:aiMode,messages:[...(aiMessages[protocol]||[])],draft:aiDrafts[protocol]||'',policy:aiPolicy,model:aiModel,effort:aiEffort,imageAuthorized,compression:aiCompression?{...aiCompression}:null};}
function currentAiSession(){let current=aiCurrentSessions[protocol];if(!current)current=aiCurrentSessions[protocol]={id:aiSessionSequence++};Object.assign(current,aiSnapshot());current.title=current.messages[0]?.slice(0,40)||current.title||'新会话 #'+current.id;return current;}
function aiSessionStatus(h){return ['controlling','accepted','verifying'].includes(h.stage)?'running':['power','boot','approval','auth','unknown'].includes(h.stage)?'approval':h.stage==='succeeded'?'success':h.stage==='rejected'||h.stage==='expired'?'failed':h.messages?.length?'success':'idle';}
function kvmAiSessionRows(){const current=currentAiSession(),all=[...Object.values(aiCurrentSessions),...aiHistory],seen=new Set();return all.filter(h=>!seen.has(h.id)&&seen.add(h.id)).map(h=>({...h,title:h.title||h.messages?.[0]?.slice(0,40)||'新会话 #'+h.id,status:aiSessionStatus(h),ownerLabel:((Object.keys(names).indexOf(h.owner)+1)||1)+' · '+(names[h.owner]||h.owner),selected:h.id===current.id}));}
